278	    take: CATALOG_LIST_CAP,
279	  });
280	  const aggs = await ratingAggs(rows.map((r) => r.id));
281	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
282	}
283	
284	export type RecommendedPlan = { planName: string; ramMB: number; priceCents: number } | null;
285	
286	/**
287	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
288	 * light-impact mods run on any active plan for the family; moderate needs at
289	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
290	 * for the family that clears the bar, or null if none does (never guesses a
291	 * number that isn't a real, active, orderable plan).
292	 */
293	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
294	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
295	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
296	  const pick = candidates[0];
297	  return pick ? { planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
298	}
299	
300	export function formatDownloads(n: number | null): string | null {
301	  if (n == null) return null;
302	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
303	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
304	  return String(n);
305	}
306	
307	export function formatBytes(bytes: number | null): string | null {
308	  if (!bytes || bytes <= 0) return null;
309	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
310	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
311	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
312	}
