314	/**
315	 * The real, authoritative download for a mod detail page. Prefers the
316	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
317	 * install it) so a visitor gets the actual file, not just a landing page;
318	 * falls back to the mod's own project/resource page (still the real,
319	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
320	 * be resolved live or isn't one of the three we know how to resolve.
321	 */
322	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
323	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
324	  const id = mod.sourceId ?? "";
325	  if (!id) return fallback;
326	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
327	  try {
328	    if (mod.source === "modrinth") {
329	      const headers: Record<string, string> = { "User-Agent": UA };
330	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
331	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
332	      if (!res.ok) return fallback;
333	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
334	      const v = versions[0];
335	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
336	      return file ? { url: file.url, direct: true } : fallback;
337	    }
338	    if (mod.source === "spigotmc") {
339	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
340	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
341	    }
342	    if (mod.source === "thunderstore") {
343	      const [namespace, ...rest] = id.split("-");
344	      if (!namespace || !rest.length) return fallback;
345	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
346	        headers: { "User-Agent": UA },
347	        next: { revalidate: 3600 },
348	      });
349	      if (!res.ok) return fallback;
350	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
351	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
352	    }
353	  } catch {
354	    return fallback;
355	  }
356	  return fallback;
357	}
